custom_css:
/* === 梦幻假日 Dreamy Holiday 海滨度假主题 感谢美化楼的老师。类名，输入框伪提示词来自尾老师，hy老师去除思维链箭头，12的去除思维链阴影，以及na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Shadows+Into+Light&display=swap'); /* 英文度假手写体 */
@import url("https://fontsapi.zeoseven.com/44/main/result.css"); /* 全局中文: undefined */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/556/main/result.css"); /* 引用: The Peak Font Plus */
@import url("https://fontsapi.zeoseven.com/498/main/result.css"); /* 标题修改: 平方刘昂乐天体 */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg-color: #E3F2FF; /* 海风浅蓝 */
    --theme-bg-mid: #BEDDFF; /* 晴空蓝 */
    --card-bg: #F2F8FF; /* 明信片底色 */
    --accent-blue: #9BCAFF; /* 深海点缀蓝 */
    --accent-coral: #FF7F50; /* 珊瑚橘（点缀） */
    --accent-sand: #EACCA1; /* 沙滩金（点缀） */
    --text-main: #2C3E50; /* 深空灰蓝，确保浅色背景下阅读清晰 */
    --text-subtle: #546E7A; /* 灰蓝色 */

    --font-english: 'Shadows Into Light', cursive;
    --font-main: "undefined", var(--font-english), sans-serif;
    --font-quote: "The Peak Font Plus", var(--font-english), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "平方刘昂乐天体", var(--font-english), sans-serif;
}

/* --- 3. 全局样式与无阴影无边框设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=2073&auto=format&fit=crop'); /* 默认海滩背景底图 */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
/* 阳光波纹遮罩层 */
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: radial-gradient(circle at top right, rgba(255,255,255,0.4), transparent 50%);
    pointer-events: none; z-index: 9999; mix-blend-mode: overlay;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-blue); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 --- */
#top-settings-holder { position:relative; background-color: rgba(227, 242, 255, 0.6); backdrop-filter: blur(10px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.4s ease; }
.drawer-icon.fa-fw:hover { transform: translateY(-5px) rotate(5deg); }

/* 你指定的导航栏贴图替换 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/U5md/1769X1730/2026-04-25_183650.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/I9vH/1638X1640/2026-04-25_183334.png/webp'); 
}

/* 抽屉与弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(242, 248, 255, 0.8), rgba(242, 248, 255, 0.9)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/laKG/1200X675/8c9658a942ee19a2b2bcf6e338509a48.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 12px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 20px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { 
    pointer-events: auto; width: 85% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: rgba(255, 255, 255, 0.7) !important; padding: 12px 20px !important; 
    backdrop-filter: blur(15px) !important; -webkit-backdrop-filter: blur(15px) !important; 
    border-radius: 30px !important; 
    transition: all 0.5s ease !important; position: relative;
    animation: gentle-wave-float 6s ease-in-out infinite;
}
@keyframes gentle-wave-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }

#rightSendForm, #leftSendForm { gap: 12px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }

/* 输入框伪提示词 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'Writing a message in a bottle... 🌊'; 
    color: var(--accent-blue); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-english); font-size: 1.3em; pointer-events: none; z-index: 10; white-space: nowrap; 
    opacity: 0.6; animation: sun-breathe 3s infinite alternate;
}
@keyframes sun-breathe { 0% { opacity: 0.4; } 100% { opacity: 0.8; text-shadow: 0 0 5px rgba(255, 255, 255, 0.8); } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 38px; height: 38px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s ease; font-size: 0; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.15) translateY(-3px) rotate(-5deg); }
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/plRg/1039X964/2026-04-25_183813.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/7QQv/1821X1560/2026-04-25_183639.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/L4VY/1513X1531/2026-04-25_183557.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/plRg/1039X964/2026-04-25_183813.png/webp'); filter: hue-rotate(90deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/7QQv/1821X1560/2026-04-25_183639.png/webp'); filter: hue-rotate(180deg); }

/* --- 6. 核心：海滨明信片消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 80px auto 60px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;
    border-radius: 8px !important; 
    backdrop-filter: blur(5px) !important;
    -webkit-backdrop-filter: blur(5px) !important;
    overflow: visible !important;
    position: relative; z-index: 10;
}

/* 明信片底纹线条 */
.mes::after {
    content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background-image: repeating-linear-gradient(transparent, transparent 28px, rgba(155, 204, 255, 0.15) 29px);
    pointer-events: none; z-index: 0; border-radius: 8px;
}

/* 所有消息框左上角的垫底书签贴纸 */
.mes::before {
    content: ''; position: absolute; 
    top: -20px; left: -35px; 
    width: 140px; height: 140px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/W32N/1920X1805/2026-04-25_184134.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: center;
    z-index: -1; pointer-events: none;
    transform: rotate(-10deg);
}

/* 消息框顶部独立海报横幅区 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 150px !important; min-height: 150px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-top-left-radius: 8px; border-top-right-radius: 8px;
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/mFyA/1575X670/%E8%93%9D%E8%89%B2%E7%BB%BF%E8%89%B2%E5%BC%A5%E6%95%A3%E6%B8%90%E5%8F%98%E9%A3%8E%E6%B4%BB%E5%8A%A8%E9%82%80%E8%AF%B7%E5%BE%AE%E4%BF%A1%E5%85%AC%E4%BC%97%E5%8F%B7%E5%B0%81%E9%9D%A2_%E5%89%AF%E6%9C%AC_%281%29.png/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/JwoQ/1463X622/%E8%93%9D%E8%89%B2%E7%BB%BF%E8%89%B2%E5%BC%A5%E6%95%A3%E6%B8%90%E5%8F%98%E9%A3%8E%E6%B4%BB%E5%8A%A8%E9%82%80%E8%AF%B7%E5%BE%AE%E4%BF%A1%E5%85%AC%E4%BC%97%E5%8F%B7%E5%B0%81%E9%9D%A2_%281%29.png/webp'); }

/* 悬浮头像框 (独立剥离在横幅上方) */
.mes .avatar {
    position: absolute;
    top: -40px; 
    width: 90px; height: 90px; 
    background: #fff !important; 
    padding: 6px !important; 
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
}
.mes[is_user="false"] .avatar { left: 25px; transform: rotate(-5deg); }
.mes[is_user="true"] .avatar { right: 25px; left: auto; transform: rotate(5deg); }
.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 50% !important; 
}

/* 左右下角的专属贴纸 (缩小尺寸并降低z-index防遮挡文字) */
.mes[is_user="false"] .mes_block::before {
    content: ''; position: absolute; bottom: -15px; left: -15px;
    width: 90px; height: 90px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/76OY/1689X1669/2026-04-25_183257.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: center;
    z-index: 0; pointer-events: none; /* z-index为0，文字设置z-index:2，完美垫底 */
    animation: wind-swing 4s infinite ease-in-out alternate;
}
.mes[is_user="true"] .mes_block::before {
    content: ''; position: absolute; bottom: -15px; right: -15px;
    width: 90px; height: 90px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/drWa/1935X1552/2026-04-25_183444.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: center;
    z-index: 0; pointer-events: none;
    animation: wind-swing 3.5s infinite ease-in-out alternate-reverse;
}
@keyframes wind-swing { 0% { transform: rotate(-3deg); } 100% { transform: rotate(5deg); } }

/* 消息主体区 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 30px 35px 40px 35px !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; z-index: 10; }
/* 文字强制z-index为2，确保永远浮在贴图之上 */
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 2; }

/* 纯美学细节：明信片邮戳特效 */
.mes_block::after {
    content: 'SUMMER VIBES \A ALOHA RESORT'; white-space: pre;
    position: absolute; top: 15px; color: rgba(155, 202, 255, 0.6);
    font-family: var(--font-english); font-size: 14px; text-align: center;
    border: 2px solid rgba(155, 202, 255, 0.5); border-radius: 50%;
    padding: 10px; z-index: 1; pointer-events: none;
}
.mes[is_user="false"] .mes_block::after { right: 30px; transform: rotate(15deg); }
.mes[is_user="true"] .mes_block::after { left: 30px; transform: rotate(-15deg); }

/* 思维链自定义 (海滨风格) */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🐚 Collecting seashells of thought... (Thinking)"; 
    font-family: var(--font-english); font-size: 18px !important; 
    color: var(--accent-blue); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 15px !important; margin-bottom: 25px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; 
    background: repeating-linear-gradient(45deg, var(--theme-bg-mid), var(--theme-bg-mid) 5px, transparent 5px, transparent 10px);
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 15px; text-align: justify; }

/* --- 楼层信息、名字、按钮与时间戳 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

/* 修复名字与头像重合：将名字向下平移到横幅的中下部 */
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -60px !important; /* 调整此值，距离mes_block更近，完美避开头像高度 */
    left: 0; right: 0; width: 100% !important; 
    align-items: center !important; background: transparent !important; 
    z-index: 100; padding: 0 40px; 
}
.mes[is_user="false"] .ch_name { justify-content: flex-end !important; }
.mes[is_user="true"] .ch_name { justify-content: flex-start !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; }
.mes .ch_name .name_text { font-family: var(--font-english); font-size: 26px !important; color: #fff !important; text-shadow: 1px 1px 3px rgba(0,0,0,0.3); }
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: var(--theme-bg-mid) !important; font-size: 14px !important; font-family: var(--font-english); }

.mesIDDisplay::before { content: 'Postcard No. '; }
.mesIDDisplay::after { content: ' 💌'; }

.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0.1; transition: opacity 0.3s ease; pointer-events: auto !important; margin-top: 15px; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(227, 242, 255, 0.8) !important; color: var(--accent-blue) !important; padding: 6px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.2s ease; font-size: 14px !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-coral) !important; color: #fff !important; transform: scale(1.1); }

#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260425/L4VY/1513X1531/2026-04-25_183557.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: gentle-wave-float 1.5s infinite ease-in-out; border: none !important; height: 45px !important; width: 45px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.5) !important; border-radius: 8px !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-blue) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.7) !important; color: var(--text-main) !important; border-radius: 6px !important; padding: 8px !important; }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255,255,255,1) !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.5) !important; color: var(--text-subtle) !important; transition: all 0.3s ease; border-radius: 8px !important; }
.menu_button:hover { background-color: var(--accent-blue) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-coral) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(242, 248, 255, 0.85); z-index: 0; border-radius: 12px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-coral) !important; color: #fff !important; }

/* 手机端适配调整 */
@media (max-width: 768px) {
    .mes { margin: 60px auto 40px !important; }
    .mes::before { width: 90px; height: 90px; top: -10px; left: -15px; }
    .mes[is_user="false"] .mes_block::before, .mes[is_user="true"] .mes_block::before { width: 70px; height: 70px; bottom: -10px; } /* 手机端贴纸更小 */
    .mes[is_user="false"] .mes_block::before { left: -10px; }
    .mes[is_user="true"] .mes_block::before { right: -10px; }
    .mes .avatar { width: 70px; height: 70px; top: -30px; }
    .mes .ch_name .name_text { font-size: 20px !important; }
    .mes .mesAvatarWrapper { height: 120px !important; min-height: 120px !important; }
    .mes .mes_block > .ch_name { top: -50px !important; padding: 0 20px; } /* 手机端名字高度同步下调 */
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.8) !important; color: var(--accent-blue) !important; border-radius: 8px !important; padding: 10px 20px !important; margin: 10px 5px !important; transition: all 0.3s ease !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-coral) !important; color: #fff !important; transform: scale(1.05) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--theme-bg-mid) !important; color: #fff !important; transform: scale(1.05) !important; }
